-- =====================================================================
-- Zentrip: COMPLETE database from scratch (new / empty Supabase project)
-- =====================================================================
-- Generated by scripts/build-supabase-sql.py - do not edit by hand.
-- Paste the WHOLE file into Supabase SQL Editor and press Run.
--
-- For a NEW, EMPTY project. For the existing production database use
-- supabase_sync_to_project.sql (it upgrades in place). Nothing here drops a
-- table that holds application data, and the file is safe to rerun.
--
--   PART 1  base schema: core tables, indexes, foreign keys, sample
--           airports and sample travel offers
--   PART 2  the 11 project migrations (ledger, runtime role and RLS,
--           landmark catalog, hotel destinations, payments, push tokens,
--           notifications, offer-flight link, favorites/alerts/settings)
--   PART 3  drop the unused users.remember_token column
--   PART 4  final check - every row must say OK
--
-- Result: 32 application tables + the schema_migrations ledger.
-- =====================================================================

-- ---------------------------------------------------------------------
-- PART 1: base schema (schema.sql)
-- ---------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS partners (
    id BIGSERIAL PRIMARY KEY,
    slug VARCHAR(100) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    service_type VARCHAR(30) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    phone VARCHAR(20) NULL,
    email_verified_at TIMESTAMPTZ NULL,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'customer',
    partner_id BIGINT NULL,
    remember_token VARCHAR(100) NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT users_partner_id_foreign FOREIGN KEY (partner_id) REFERENCES partners(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS users_partner_id_index ON users (partner_id);

CREATE TABLE IF NOT EXISTS password_reset_codes (
    email VARCHAR(255) NOT NULL PRIMARY KEY,
    code_hash CHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT password_reset_codes_expires_at_index CHECK (expires_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS password_reset_codes_expires_at_index ON password_reset_codes (expires_at);

CREATE TABLE IF NOT EXISTS partner_listings (
    id BIGSERIAL PRIMARY KEY,
    partner_id BIGINT NOT NULL,
    type VARCHAR(30) NOT NULL,
    title VARCHAR(255) NOT NULL,
    city VARCHAR(255) NOT NULL DEFAULT '',
    country VARCHAR(255) NOT NULL DEFAULT '',
    description TEXT NULL,
    image_url VARCHAR(2048) NULL,
    price DECIMAL(10,2) NOT NULL DEFAULT 0,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    attributes JSONB NOT NULL,
    location_name VARCHAR(512) NULL,
    google_maps_url VARCHAR(2048) NULL,
    place_id VARCHAR(255) NULL,
    google_rating DECIMAL(2,1) NOT NULL DEFAULT 0.0,
    google_review_count INTEGER NOT NULL DEFAULT 0,
    amenities JSONB NULL,
    tax_and_fees_percentage DECIMAL(5,2) NOT NULL DEFAULT 12.00,
    available_rooms INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT partner_listings_partner_foreign FOREIGN KEY (partner_id) REFERENCES partners(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS partner_listings_type_city_index ON partner_listings (type, city, active);
CREATE INDEX IF NOT EXISTS partner_listings_partner_index ON partner_listings (partner_id, active);
CREATE INDEX IF NOT EXISTS partner_listings_city_trgm_index
    ON partner_listings USING GIN (city gin_trgm_ops);
CREATE INDEX IF NOT EXISTS partner_listings_title_trgm_index
    ON partner_listings USING GIN (title gin_trgm_ops);
CREATE INDEX IF NOT EXISTS partner_listings_attributes_gin_index
    ON partner_listings USING GIN (attributes);

CREATE TABLE IF NOT EXISTS airports (
    code CHAR(3) NOT NULL PRIMARY KEY,
    city VARCHAR(100) NOT NULL,
    airport_name VARCHAR(255) NOT NULL,
    country VARCHAR(100) NOT NULL,
    region VARCHAR(100) NOT NULL,
    icao_code CHAR(4),
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    airport_type VARCHAR(32) NOT NULL DEFAULT 'medium_airport',
    is_major BOOLEAN NOT NULL DEFAULT FALSE,
    scheduled_service BOOLEAN NOT NULL DEFAULT TRUE,
    iso_country CHAR(2),
    keywords TEXT NOT NULL DEFAULT '',
    wikipedia_link VARCHAR(2048),
    source_id BIGINT,
    source_provider VARCHAR(32) NOT NULL DEFAULT 'legacy',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE airports ADD COLUMN IF NOT EXISTS icao_code CHAR(4);
ALTER TABLE airports ADD COLUMN IF NOT EXISTS latitude DOUBLE PRECISION;
ALTER TABLE airports ADD COLUMN IF NOT EXISTS longitude DOUBLE PRECISION;
ALTER TABLE airports ADD COLUMN IF NOT EXISTS airport_type VARCHAR(32) NOT NULL DEFAULT 'medium_airport';
ALTER TABLE airports ADD COLUMN IF NOT EXISTS is_major BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE airports ADD COLUMN IF NOT EXISTS scheduled_service BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE airports ADD COLUMN IF NOT EXISTS iso_country CHAR(2);
ALTER TABLE airports ADD COLUMN IF NOT EXISTS keywords TEXT NOT NULL DEFAULT '';
ALTER TABLE airports ADD COLUMN IF NOT EXISTS wikipedia_link VARCHAR(2048);
ALTER TABLE airports ADD COLUMN IF NOT EXISTS source_id BIGINT;
ALTER TABLE airports ADD COLUMN IF NOT EXISTS source_provider VARCHAR(32) NOT NULL DEFAULT 'legacy';
ALTER TABLE airports ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
CREATE INDEX IF NOT EXISTS airports_city_index ON airports (city);
CREATE INDEX IF NOT EXISTS airports_icao_code_index ON airports (icao_code);
CREATE INDEX IF NOT EXISTS airports_country_city_index ON airports (iso_country, city);
CREATE INDEX IF NOT EXISTS airports_city_search_index ON airports (LOWER(city));
CREATE INDEX IF NOT EXISTS airports_country_search_index ON airports (LOWER(country));
CREATE INDEX IF NOT EXISTS airports_name_search_index ON airports (LOWER(airport_name));
CREATE INDEX IF NOT EXISTS airports_coordinates_index ON airports (latitude, longitude)
    WHERE latitude IS NOT NULL AND longitude IS NOT NULL;

